<template>
   <div class="violation-settings">
      <div class="violation-settings__header">
         <div class="violation-settings__title">
            <img src="@/assets/icons/stop.svg" alt="stop" />
            <h3>Нарушения</h3>
         </div>
         <button class="violation-settings__add" @click="isAdding = true">
            <img src="@/assets/icons/addad-blue.svg" alt="add" />
            Добавить
         </button>
      </div>

      <div class="divider" />

      <!-- Форма добавления -->
      <div v-if="isAdding" class="violation-settings__form">
         <input v-model="newViolation.title" placeholder="Название нарушения" />
         <div class="violation-settings__form-actions">
            <button class="create-btn" @click="createViolation">Создать</button>
            <button class="cancel-btn" @click="cancelAdd">Отменить</button>
         </div>
      </div>

      <!-- Список нарушений -->
      <div class="violation-settings__list">
         <div v-for="(violation, index) in violations" :key="index" class="violation-settings__item">
            <div v-if="editedIndex !== index">
               <strong>{{ violation.title }}</strong>
               <p>{{ violation.subtitle }}</p>
            </div>

            <div v-else class="violation-settings__form">
               <input v-model="editTitle" />
               <div class="violation-settings__form-actions">
                  <button class="create-btn" @click="saveEdit(index)">Сохранить</button>
                  <button class="cancel-btn" @click="cancelEdit">Отменить</button>
               </div>
            </div>

            <div class="violation-settings__item-actions" v-if="editedIndex !== index">
               <button @click="startEdit(index, violation.title)">
                  <img src="@/assets/icons/edit.svg" alt="edit" />
               </button>
               <button @click="deleteViolation(index)">
                  <img src="@/assets/icons/delete.svg" alt="delete" />
               </button>
            </div>
         </div>
      </div>

      <div class="violation-settings__footer">
         <div class="divider" />
         <ButtonUI buttonClass="btn--second" text="Отменить" @click="cancelAll" />
      </div>
   </div>
</template>

<script setup>
import { ref } from 'vue';
import ButtonUI from '@/components/UI/ButtonUI.vue';
import { defineEmits } from 'vue';

const emit = defineEmits(['close']);

const isAdding = ref(false);
const newViolation = ref({
   title: '',
});
const violations = ref([
   {
      title: 'Спам',
      subtitle: 'Сергей Олегович, 14.12.2024',
   },
   {
      title: 'Оскорбления',
      subtitle: 'Сергей Олегович, 14.12.2024',
   },
]);

const editedIndex = ref(null);
const editTitle = ref('');

const createViolation = () => {
   const title = newViolation.value.title.trim();
   if (title) {
      const date = new Date().toLocaleDateString('ru-RU');
      violations.value.push({
         title,
         subtitle: `Сергей Олегович, ${date}`,
      });
      newViolation.value.title = '';
      isAdding.value = false;
   }
};

const cancelAdd = () => {
   newViolation.value.title = '';
   isAdding.value = false;
};

const cancelAll = () => {
   isAdding.value = false;
   editedIndex.value = null;
   newViolation.value.title = '';
   editTitle.value = '';
   emit('close');
};

const startEdit = (index, title) => {
   editedIndex.value = index;
   editTitle.value = title;
};

const saveEdit = (index) => {
   const title = editTitle.value.trim();
   if (title) {
      violations.value[index].title = title;
      editedIndex.value = null;
      editTitle.value = '';
   }
};

const cancelEdit = () => {
   editedIndex.value = null;
   editTitle.value = '';
};

const deleteViolation = (index) => {
   violations.value.splice(index, 1);
};
</script>

