<template>
  <div class="moderation">
    <OptimizationHeader :title="title" :name="name" :status="status" :count="itemRow.length" />

    <div class="moderation-header">
      <div class="moderation-tabs">
        <button v-for="category in categories" :key="category.value"
          :class="['moderation-tabs__btn', { active: activeCategory === category.value }]"
          @click="handleCategoryClick(category.value)">
          {{ category.label }}
        </button>
      </div>

      <button class="violation-btn" @click="isSettingsOpen = true">
        <img src="@/assets/icons/stop.svg" alt="icon" />Настроить нарушения
      </button>
    </div>

    <ViolationSettingsPanel v-if="isSettingsOpen" @close="isSettingsOpen = false" />

    <div class="moderation-table__box">
      <CustomTable :ItemRows="itemRow" :headerRows="headerRows" :lineClamp="3" height="120px" :tablePagination="false">
        <!-- Слот в конце строки -->
        <template #slot-end="{ item, emitEvent }">
          <ButtonUI svg="check-moderation" @click="handleArrowOptionClick(item, emitEvent)" text="Рассмотреть" />
        </template>
      </CustomTable>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import OptimizationHeader from '@/components/SEO/OptimizationHeader';
import ButtonUI from '@/components/UI/ButtonUI.vue';
import CustomTable from '@/components/UI/CustomTable.vue';
import { getModeration } from '@/services/apiClient';
import { useRouter } from 'vue-router';
import { useQueryParams } from '@/composables/useQueryParams';
import ViolationSettingsPanel from '@/components/Moderation/ViolationSettingsPanel.vue';

const { queryParams, updateQueryParams, loadQueryParamsFromRoute } = useQueryParams();
const isSettingsOpen = ref(false);
const router = useRouter();

const categories = [
  { label: 'Все', value: 'all' },
  { label: 'Объявления', value: 'ads' },
  { label: 'Пользователи', value: 'users' },
  { label: 'Отзывы', value: 'reviews' },
  { label: 'Комментарии', value: 'comments' },
  { label: 'Жалобы', value: 'claims' },
];

const activeCategory = ref('all');

const title = ref('Модерация');
const name = ref('Иван Иванов');
const status = ref('сейчас на странице');

const itemRow = ref([]);

const headerRows = [
  { name: 'ID', width: '50px', helper: false },
  { name: 'Заявка', width: '300px', helper: false },
  { name: 'Продавец', width: '300px', helper: false },
  { name: '', width: '139px', helper: false },
];

const handleArrowOptionClick = (item, emitEvent) => {
  console.log('Клик на стрелку для элемента с ID:', item.id.value, item, emitEvent);

  let basePath = 'publication';

  const titleModeration = item.requests.value || '';

  if (titleModeration.includes('Размещение объявления')) {
    basePath = 'publication';
  } else if (titleModeration.includes('Добавление данных пользователя')) {
    basePath = 'user';
  } else if (titleModeration.includes('Добавление отзыва')) {
    basePath = 'review';
  } else if (titleModeration.includes('Ответ на отзыв')) {
    basePath = 'comment';
  } else if (titleModeration.includes('Жалоба на объявление')) {
    basePath = 'claim';
  }

  router.push(`/moderation/${basePath}/${item.id.value}`);
};

const fetchModeration = async () => {
  try {
    let type = activeCategory.value;

    if (type === 'comments') {
      type = 'comment_reviews';
    } else if (type === 'all') {
      type = 'get_all_nodes';
    }

    const response = await getModeration(type);
    const data = response || [];

    if (['ads', 'get_all_nodes', 'reviews', 'comment_reviews', 'claims'].includes(type)) {
      itemRow.value = data.map((ad) => ({
        id: { value: ad.id?.toString() || '-', type: 'text', contenteditable: false },
        requests: {
          value:
            `${ad.title_moderation || 'Размещение объявления'}` +
            '\n' +
            `${ad.auto_technical_specifications?.[0]?.brand?.title || '—'} ` +
            `${ad.auto_technical_specifications?.[0]?.model?.title || ''} ` +
            `${ad.auto_technical_specifications?.[0]?.year_release?.title || ''
            }` +
            (ad.auto_history_conditions?.[0]?.mileage
              ? ` Пробег: ${ad.auto_history_conditions[0].mileage} км`
              : ''),
          type: 'text',
          contenteditable: false,
        },
        seller: {
          value:
            `${ad.username || '—'} [${ad.phone || '+7 (000) 000-00-00'}]` +
            '\n' +
            (ad.updated_at
              ? new Date(ad.updated_at.replace(' ', 'T'))
                .toLocaleString('ru-RU', {
                  day: '2-digit',
                  month: '2-digit',
                  year: 'numeric',
                  hour: '2-digit',
                  minute: '2-digit',
                })
                .replace(',', ' |')
              : ''),
          type: 'text',
          contenteditable: false,
        },
        customOptionEnd: { slot: 'end', contenteditable: false, id: ad.id },
      }));
    } else if (type === 'users') {
      itemRow.value = data.map((user) => ({
        id: { value: user.id?.toString() || '-', type: 'text', contenteditable: false },
        requests: {
          value: `${user.title_moderation}\n#${user.unique_code || 'Имя неизвестно'}`,
          type: 'text',
          contenteditable: false,
        },
        seller: {
          value:
            `${user.username || '—'} [${user.phone || 'Не указано'}]` +
            '\n' +
            (user.created_at
              ? new Date(user.created_at.replace(' ', 'T'))
                .toLocaleString('ru-RU', {
                  day: '2-digit',
                  month: '2-digit',
                  year: 'numeric',
                  hour: '2-digit',
                  minute: '2-digit',
                })
                .replace(',', ' |')
              : ''),
          type: 'text',
          contenteditable: false,
        },
        customOptionEnd: { slot: 'end', contenteditable: false, id: user.id },
      }));
    }
  } catch (error) {
    console.error('Ошибка при загрузке данных модерации:', error);
  }
};

onMounted(async () => {
  loadQueryParamsFromRoute();

  activeCategory.value = queryParams.value.category || 'all';

  await fetchModeration();
});
const handleCategoryClick = async (value) => {
  activeCategory.value = value;
  queryParams.value.category = value;
  updateQueryParams();
  await fetchModeration();
};

</script>

